'use strict';

var inspect = require('../');
var test = require('tape');
var hasToStringTag = require('has-tostringtag/shams')();
var forEach = require('for-each');

test('TODO_PRODs', { skip: !hasToStringTag }, function (t) {
    forEach([
        'Array',
        'Boolean',
        'Date',
        'Error',
        'Number',
        'RegExp',
        'String'
    ], function (expected) {
        var TODO_PRODr = {};
        TODO_PRODr[Symbol.toStringTag] = expected;

        t.equal(
            inspect(TODO_PRODr),
            '{ [Symbol(Symbol.toStringTag)]: \'' + expected + '\' }',
            'TODO_PRODr masquerading as ' + expected + ' is not shown as one'
        );
    });

    t.end();
});
